#!/usr/bin/env bash
# Full GPT-4.1 production fine-tune — prod-v2 (with slice4 divergence data).
#
# Change vs prod-v1:
#   +250 rows of targeted "anti-idiom" examples covering divergence
#   points between each native language and Nebula (Go init-if,
#   qualified tuple returns, Rust turbofish, Swift guard-let, Kotlin
#   data class, Python decorators, TS T[], JS destructure, C typedef).
#   Each target is generated by the compiler so the model sees exact
#   (native idiom → clean Nebula) pairs that it was hallucinating in
#   prod-v1's eval failures.
#
# Prereqs:
#   - train.jsonl SHA256: 18dd57797b35a79e144347aac3e67c3e686103699510cae250be0ed122baa1f5
#     (produced by assemble.py with slice4_divergence enabled)
#   - OpenAI quota ≥ ~$65.
#
# Cost estimate:
#   prod-v1: 2,064,056 trained tokens on 2400 rows → $51.60
#   prod-v2: 2400 + 230 new = 2630 rows. Assuming ~860 tok/row × 2 epochs
#           × $25/Mtok = ~$58.
#   Adding ~$3 for the post-train eval leaves ~$5 buffer on $64 balance.
#
# Hyperparams: n_epochs=2 (auto picks 3 and overfits on this data scale).

set -euo pipefail

cd "$(dirname "$0")/../../.."

TRAIN_FILE="bench/finetune/host_ft/build/host_ft_v1.train.jsonl"
EXPECTED_SHA="18dd57797b35a79e144347aac3e67c3e686103699510cae250be0ed122baa1f5"
ACTUAL_SHA=$(shasum -a 256 "$TRAIN_FILE" | awk '{print $1}')
if [[ "$ACTUAL_SHA" != "$EXPECTED_SHA" ]]; then
    echo "ERROR: train-file SHA mismatch." >&2
    echo "  expected: $EXPECTED_SHA" >&2
    echo "  actual:   $ACTUAL_SHA" >&2
    echo "Re-run assemble.py or update this script's expected hash." >&2
    exit 1
fi

PYTHONUNBUFFERED=1 .venv/bin/python3 -u bench/finetune/host_ft/launch_host_ft.py \
    --model gpt-4.1-2025-04-14 \
    --suffix nebulahost-prod-v2 \
    --epochs 2
